
const paths={message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/>',pin:'<path d="M12 17v5M5 17h14v-2l-3-3V5l1-1V3H7v1l1 1v7l-3 3z"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18"/><ellipse cx="12" cy="12" rx="4" ry="9"/>',review:'<circle cx="6" cy="3" r="2"/><path d="M6 5v14M18 6a4 4 0 0 0-4-4m4 4v13"/><circle cx="6" cy="21" r="2"/><circle cx="18" cy="21" r="2"/>',book:'<path d="M12 7v14M3 3h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5v16h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3z"/>',check:'<path d="m5 12 4 4L19 6"/>',checks:'<path d="m3 6 2 2 4-4M13 6h8M3 16l2 2 4-4M13 16h8"/>',down:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m9 6 6 6-6 6"/>',back:'<path d="m15 6-6 6 6 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const pins=[{id:'preview',title:'Development preview',host:'preview.example.test',icon:'globe',message:'Mobile navigation is ready to try.',kind:'Updated'}, {id:'review',title:'Review changes',host:'github.com',icon:'review',message:'Addressed your feedback on spacing.',kind:'Updated'}, {id:'guide',title:'Plugin guide',host:'paseo.sh',icon:'book',message:'',kind:'Added'}];
const longMessage='Mobile navigation now supports narrow screens, keyboard focus, and longer workspace names. Please try the menu on your phone and check that switching workspaces keeps your current tab selected.';
const variant=document.body.dataset.variant;let unread=new Set(['preview','review']),long=false,collapsed=false;const expanded=new Set();
const escape=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
function row(p,surface){const key=surface+'-'+p.id,isRead=!unread.has(p.id),message=long&&p.id==='preview'?longMessage:p.message;const meta=`<span class="metadata" data-dc-id="${key}-domain">${surface==='chat'?p.kind+' · ':''}${p.host}</span>`;const note=message?`<div class="message ${expanded.has(key)?'expanded':''}" data-dc-id="${key}-message">${variant==='message-icon'||variant==='message-dot'?`<span class="message-marker" data-dc-id="${key}-message-marker" aria-hidden="true">${variant==='message-icon'?icon('message'):'<span class="message-dot"></span>'}</span>`:''}<span class="message-text">${escape(message)}</span><button class="more" data-more="${key}" aria-label="${expanded.has(key)?'Show less of update':'Read full update'}" title="${expanded.has(key)?'Show less':'Read full update'}" aria-expanded="${expanded.has(key)}" data-dc-id="${key}-message-toggle" ${!(long&&p.id==='preview')?'hidden':''}>${expanded.has(key)?'Show less':'Read more'}</button></div>`:'';return `<div class="row ${isRead?'read':''}" data-key="${p.id}" data-dc-id="${key}-row"><span class="resource" data-dc-id="${key}-icon">${icon(p.icon)}<span class="dot"></span></span><div class="copy"><button class="link" data-open="${p.id}" aria-label="Open ${p.title}${isRead?'':', unread update'}" data-dc-id="${key}-link"><span class="title">${p.title}</span></button>${meta+note}</div>${surface==='menu'?`<button class="icon-button ack" data-read="${p.id}" title="Mark as read" aria-label="Mark ${p.title} as read" data-dc-id="${key}-mark-read" ${isRead?'disabled':''}>${icon('check')}</button>`:''}</div>`}
function render(){document.querySelector('.menu-list').innerHTML=pins.map(p=>row(p,'menu')).join('');document.querySelector('.chat-body').innerHTML=pins.map(p=>row(p,'chat')).join('');document.querySelectorAll('[data-count]').forEach(e=>e.textContent='Pins'+(unread.size?' ('+unread.size+')':''));document.querySelectorAll('[data-read-all]').forEach(e=>e.disabled=!unread.size);document.querySelector('.chat-body').hidden=collapsed;document.querySelectorAll('[data-collapse]').forEach(e=>e.setAttribute('aria-expanded',String(!collapsed)));const toggle=document.querySelector('[data-collapse-icon]');toggle.innerHTML=icon(collapsed?'right':'down');toggle.setAttribute('aria-label',collapsed?'Expand pins':'Collapse pins');document.querySelector('[data-long]').textContent=long?'Short message':'Try a long message';}
const feedback=t=>document.querySelector('[data-feedback]').textContent=t;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-read')){unread.delete(b.dataset.read);feedback('Marked read in both surfaces. The message stays in chat history.');}else if(b.hasAttribute('data-open')){unread.delete(b.dataset.open);feedback('Simulated opening the link and marking its captured update read.');}else if(b.hasAttribute('data-read-all')){unread.clear();feedback('Both captured updates marked read. New pins were already read.');}else if(b.hasAttribute('data-more')){const key=b.dataset.more;expanded.has(key)?expanded.delete(key):expanded.add(key);}else if(b.hasAttribute('data-collapse')){collapsed=!collapsed;}else if(b.hasAttribute('data-long')){long=!long;}else if(b.hasAttribute('data-reset')){unread=new Set(['preview','review']);collapsed=false;long=false;expanded.clear();feedback('Prototype reset. Sample links only; live pins are unchanged.');}else return;render();});render();
